function tick(now) {
  try {
    const dt = Math.min((now - lastTime)/1000, 0.1);
    lastTime = now;
    // update
    if (phase === "playing") {
      // lateral movement
      const dirX = (keys.has("ArrowRight") || keys.has("d") || keys.has("D") ? 1 : 0) - (keys.has("ArrowLeft") || keys.has("a") || keys.has("A") ? 1 : 0);
      player.x += dirX * LATERAL_SPEED * dt;
      // forward
      player.y += FORWARD_SPEED * dt;
      // clamp player within canvas
      const canvas = document.getElementById("game");
      player.x = Math.max(0, Math.min(canvas.width, player.x));
      player.y = Math.max(0, Math.min(canvas.height, player.y));
    }

    // render
